class Solution {
public:
    int minSumOfLengths(vector<int>& arr, int target) {
        int n = arr.size();
        vector<int> dp(n, INT_MAX);
        int ans = INT_MAX;
        int l = 0, sum = 0;
        for (int r = 0; r < n; r++) {
            sum += arr[r];
            while (sum > target && l <= r) {
                sum -= arr[l];
                l++;
            }
            if (sum == target) {
                int len = r - l + 1;
                if (l > 0 && dp[l - 1] != INT_MAX) {
                    ans = min(ans, len + dp[l - 1]);
                }
                dp[r] = len;
            }
            if (r > 0) {
                dp[r] = min(dp[r], dp[r - 1]);
            }
        }
        return ans == INT_MAX ? -1 : ans;
    }
};
